  add column if not exists research_contact_opt_in boolean not null default false,
  -- Consent provenance for regulatory requests (version, timestamp, IP, UA, evidence blob)
  add column if not exists consent_policy_version text,
  add column if not exists consent_captured_at timestamptz,
  add column if not exists consent_captured_ip inet,
  add column if not exists consent_captured_user_agent text,
  add column if not exists consent_evidence jsonb not null default '{}'::jsonb,
  add column if not exists privacy_review_required boolean not null default false,
