-- =============================================================================
-- SECTION: Priority queues and entitlements (plans, billing, usage)
-- =============================================================================
-- Wires subscription-tier priority into plans, live subscription snapshots,
-- token accounting, and daily rollups. priority_rank is numeric (higher = sooner
-- in queue). highest_priority_* flags gate Nomita “jump the queue” behavior;
-- plus_highest_priority_blocked prevents Plus from claiming highest tier.

-- plans — canonical priority / peak / training entitlements per SKU
alter table public.plans
  add column if not exists service_level text not null default 'standard',
  add column if not exists priority_rank integer not null default 10,
  add column if not exists highest_priority_eligible boolean not null default false,
  add column if not exists peak_priority_weight numeric(8,4) not null default 1.0000,
  add column if not exists dedicated_capacity_eligible boolean not null default false,
  add column if not exists burst_multiplier numeric(8,4) not null default 1.0000,
  add column if not exists soft_limit_multiplier numeric(8,4) not null default 1.0000,
  add column if not exists queue_jump_allowed boolean not null default false,
  add column if not exists plus_highest_priority_blocked boolean not null default false,
  add column if not exists training_default_opt_in_allowed boolean not null default false,
  add column if not exists enterprise_controls_enabled boolean not null default false,
  add column if not exists business_controls_enabled boolean not null default false,
  add column if not exists support_response_sla_minutes integer,
  add column if not exists model_access_policy jsonb not null default '{}'::jsonb,
  add column if not exists rate_limit_policy jsonb not null default '{}'::jsonb,
  add column if not exists peak_time_policy jsonb not null default '{}'::jsonb,
  add column if not exists training_policy jsonb not null default '{}'::jsonb,
  add column if not exists governance_notes text,
  add column if not exists effective_from timestamptz not null default now();

