-- =============================================================================
-- SECTION: Governance tables (append-only / operational control plane)
-- =============================================================================
-- New first-class tables for consent history, realtime usage buckets, per-request
-- priority decisions, and provider capacity windows. Writes are expected from
-- edge workers / service_role; clients read only where RLS policies allow.

-- Immutable consent transitions (append-only; do not UPDATE rows in application code)
create table if not exists public.model_training_consent_events (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references auth.users(id) on delete cascade,
  workspace_id uuid references public.workspaces(id) on delete cascade,
  subject_type text not null default 'user',
  subject_id text,
  plan_id text references public.plans(id),
  service_level text,
  consent_state text not null,
  consent_scope text not null default 'none',
  allowed_modalities text[] not null default '{}'::text[],
  blocked_categories text[] not null default '{}'::text[],
  data_classification text,
  policy_version text,
  source text not null default 'settings',
  source_ip inet,
  source_user_agent text,
  evidence jsonb not null default '{}'::jsonb,
  effective_at timestamptz not null default now(),
  expires_at timestamptz,
  revoked_at timestamptz,
  created_at timestamptz not null default now()
);

-- Rolling realtime aggregates per provider/model/plan window (feeds dashboards + realtime)
create table if not exists public.model_usage_realtime_windows (
  id uuid primary key default gen_random_uuid(),
  window_start timestamptz not null,
  window_end timestamptz not null,
  bucket_seconds integer not null default 60,
  provider text not null default 'nomita',
  model_id text,
  model_family text,
  region text,
  capacity_pool text,
  service_level text not null default 'standard',
  plan_id text references public.plans(id),
  priority_rank integer not null default 10,
  highest_priority boolean not null default false,
  active_requests integer not null default 0,
  queued_requests integer not null default 0,
  completed_requests integer not null default 0,
  failed_requests integer not null default 0,
  throttled_requests integer not null default 0,
  training_eligible_requests integer not null default 0,
  training_blocked_requests integer not null default 0,
  input_tokens bigint not null default 0,
  output_tokens bigint not null default 0,
  cost_amount numeric(18,8),
  avg_latency_ms numeric(12,2),
  p95_latency_ms numeric(12,2),
  saturation_ratio numeric(8,4),
  queue_depth integer not null default 0,
  capacity_units integer,
  nomita_capacity_snapshot jsonb not null default '{}'::jsonb,
  routing_snapshot jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Per-request priority routing decision log (debugging queue fairness disputes)
create table if not exists public.model_priority_runtime_snapshots (
  id uuid primary key default gen_random_uuid(),
  request_id text,
  user_id uuid references auth.users(id) on delete set null,
  workspace_id uuid references public.workspaces(id) on delete set null,
  subscription_id uuid references public.subscriptions(id) on delete set null,
  plan_id text references public.plans(id),
  service_level text not null default 'standard',
  priority_rank integer not null default 10,
  highest_priority boolean not null default false,
  plus_highest_priority_blocked boolean not null default true,
  peak_window boolean not null default false,
  provider text not null default 'nomita',
  model_id text,
  capacity_pool text,
  queue_position integer,
  queue_wait_ms integer,
  decision text not null default 'allow',
  decision_reason text,
  router_rule_id uuid references public.model_router_rules(id) on delete set null,
  entitlement_snapshot jsonb not null default '{}'::jsonb,
  rate_limit_snapshot jsonb not null default '{}'::jsonb,
  provider_snapshot jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);

-- Provider-side capacity telemetry buckets (feeds autoscaling / throttle recommendations)
create table if not exists public.provider_capacity_windows (
  id uuid primary key default gen_random_uuid(),
  provider text not null default 'nomita',
  model_id text,
  model_family text,
  region text,
  capacity_pool text,
  window_start timestamptz not null,
  window_end timestamptz not null,
  max_qps numeric(12,4),
  observed_qps numeric(12,4),
  max_concurrency integer,
  observed_concurrency integer,
  queue_depth integer,
  saturation_ratio numeric(8,4),
  error_rate numeric(8,4),
  throttle_rate numeric(8,4),
  health_state text not null default 'unknown',
  recommended_priority_floor integer,
  recommended_throttle_policy text,
  nomita_payload jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);


-- =============================================================================
-- SECTION: Row-level security (RLS)
-- =============================================================================
-- Enable RLS on all new tables. Users may SELECT their own consent events and
-- priority snapshots. Realtime/capacity windows are internal ops data — no
-- authenticated SELECT policies (service_role / dashboard roles only).

alter table public.model_training_consent_events enable row level security;

alter table public.model_usage_realtime_windows enable row level security;

alter table public.model_priority_runtime_snapshots enable row level security;

alter table public.provider_capacity_windows enable row level security;

drop policy if exists "Users can read own training consent events" on public.model_training_consent_events;

create policy "Users can read own training consent events"
on public.model_training_consent_events
for select
to authenticated
using (user_id = (select auth.uid()));

drop policy if exists "Users can read own priority snapshots" on public.model_priority_runtime_snapshots;

create policy "Users can read own priority snapshots"
on public.model_priority_runtime_snapshots
for select
to authenticated
using (user_id = (select auth.uid()));

-- model_usage_realtime_windows and provider_capacity_windows: RLS enabled, no
-- client-facing policies — operational telemetry visible via service_role /
-- dashboard_user / supabase_read_only_user grants below.


-- =============================================================================
-- SECTION: Seed plan priority semantics
-- =============================================================================
-- Materializes priority_rank, service_level, and JSON policy blobs on known SKUs.
-- Plus is explicitly non-highest (plus_highest_priority_blocked). Max/Team/Business
-- tiers that already expose highest_priority in product are marked eligible.
-- training_default_opt_in_allowed is false for all seeded plans (explicit consent).

update public.plans
set
  service_level = case
    when id in ('enterprise') then 'enterprise'
    when id in ('team', 'business', 'max', 'max5x', 'max20x') then 'business'
    when id in ('pro') then 'pro'
    when id in ('plus') then 'plus'
    when id in ('go') then 'go'
    else 'free'
  end,
  priority_rank = case
    when id in ('enterprise') then 100
    when id in ('team', 'business', 'max20x') then 95
    when id in ('max', 'max5x') then 90
    when id in ('pro') then 80
    when id in ('plus') then 40
    when id in ('go') then 20
    else 10
  end,
  highest_priority_eligible = id in ('enterprise', 'team', 'business', 'max', 'max5x', 'max20x', 'pro'),
  plus_highest_priority_blocked = id in ('plus'),
  dedicated_capacity_eligible = id in ('enterprise', 'team', 'business', 'max20x'),
  queue_jump_allowed = id in ('enterprise', 'team', 'business', 'max', 'max5x', 'max20x', 'pro'),
  enterprise_controls_enabled = id in ('enterprise'),
  business_controls_enabled = id in ('enterprise', 'team', 'business', 'max', 'max5x', 'max20x'),
  training_default_opt_in_allowed = id in ('enterprise', 'team', 'business') and false,
  peak_priority_weight = case
    when id in ('enterprise') then 4.0000
    when id in ('team', 'business', 'max20x') then 3.5000
    when id in ('max', 'max5x') then 3.0000
    when id in ('pro') then 2.2500
    when id in ('plus') then 1.2500
    when id in ('go') then 1.1000
    else 1.0000
  end,
  peak_time_policy = coalesce(peak_time_policy, '{}'::jsonb) ||
    jsonb_build_object(
      'highestPriorityOnlyFor', array['pro', 'business', 'enterprise'],
      'plusHighestPriorityBlocked', true,
      'provider', 'nomita'
    ),
  rate_limit_policy = coalesce(rate_limit_policy, '{}'::jsonb) ||
    jsonb_build_object(
      'priorityRank', case
        when id in ('enterprise') then 100
        when id in ('team', 'business', 'max20x') then 95
        when id in ('max', 'max5x') then 90
        when id in ('pro') then 80
        when id in ('plus') then 40
        when id in ('go') then 20
        else 10
      end
    ),
  training_policy = coalesce(training_policy, '{}'::jsonb) ||
    jsonb_build_object(
      'defaultOptIn', false,
      'requiresExplicitUserConsent', true,
      'enterpriseMayDisableOrgWide', true
    )
where id in ('free', 'go', 'plus', 'pro', 'max', 'max5x', 'max20x', 'team', 'business', 'enterprise');

-- Backfill subscription snapshots from current plan rows for active/trialing subs
update public.subscriptions s
set
  service_level_snapshot = p.service_level,
  priority_rank_snapshot = p.priority_rank,
  highest_priority_active = p.highest_priority_eligible and s.status in ('active', 'trialing'),
  peak_priority_weight_snapshot = p.peak_priority_weight,
  training_entitlement_snapshot = jsonb_build_object(
    'defaultOptIn', false,
    'requiresExplicitUserConsent', true,
    'planId', p.id,
    'serviceLevel', p.service_level
  ),
  nomita_priority_group = case
    when p.highest_priority_eligible and s.status in ('active', 'trialing') then p.service_level
    else 'standard'
  end,
  last_priority_recalculated_at = now()
from public.plans p
where s.plan_id = p.id;


-- =============================================================================
-- SECTION: Indexes (operational lookups; no blanket JSONB GIN)
-- =============================================================================
-- Targeted B-tree indexes on hot filter columns. Unique indexes on window tables
-- enforce idempotent upserts from edge aggregators.

create index if not exists profiles_training_consent_idx
on public.profiles (training_eligibility_default, training_consent_scope, updated_at desc);

create index if not exists user_settings_training_consent_idx
on public.user_settings (data_training_opt_in, data_training_scope, updated_at desc);

create index if not exists workspaces_priority_tier_idx
on public.workspaces (priority_tier, plan_id, updated_at desc);

create index if not exists subscriptions_priority_active_idx
on public.subscriptions (highest_priority_active, priority_rank_snapshot desc, current_period_end desc)
where status in ('active', 'trialing');

create index if not exists model_usage_events_priority_created_idx
on public.model_usage_events (provider, highest_priority, priority_rank desc, created_at desc);

create index if not exists model_usage_events_training_created_idx
on public.model_usage_events (training_eligible, created_at desc);

create index if not exists rate_limits_priority_window_idx
on public.rate_limits (provider, service_level, priority_rank desc, window_start);

create index if not exists model_router_rules_peak_priority_idx
on public.model_router_rules (is_enabled, peak_only, priority_rank_min, priority_rank_max, priority);

create index if not exists provider_health_capacity_checked_idx
on public.provider_health_checks (provider, capacity_pool, checked_at desc);

create index if not exists model_training_consent_events_user_created_idx
on public.model_training_consent_events (user_id, created_at desc);

create index if not exists model_training_consent_events_workspace_created_idx
on public.model_training_consent_events (workspace_id, created_at desc);

create index if not exists model_usage_realtime_windows_lookup_idx
on public.model_usage_realtime_windows (window_start desc, provider, service_level, priority_rank desc);

create unique index if not exists model_usage_realtime_windows_unique_idx
on public.model_usage_realtime_windows (
  window_start,
  provider,
  coalesce(model_id, ''),
  coalesce(region, ''),
  coalesce(capacity_pool, ''),
  service_level,
  coalesce(plan_id, '')
);

create index if not exists model_priority_snapshots_request_idx
on public.model_priority_runtime_snapshots (request_id)
where request_id is not null;

create index if not exists model_priority_snapshots_user_created_idx
on public.model_priority_runtime_snapshots (user_id, created_at desc);

create index if not exists provider_capacity_windows_lookup_idx
on public.provider_capacity_windows (provider, window_start desc, capacity_pool);

create unique index if not exists provider_capacity_windows_unique_idx
on public.provider_capacity_windows (
  provider,
  coalesce(model_id, ''),
  coalesce(region, ''),
  coalesce(capacity_pool, ''),
  window_start
);


