-- SECTION: Realtime publication, grants, schema reload
-- =============================================================================

-- Expose realtime windows to Supabase Realtime subscribers (dashboards, internal tools)
do $$
begin
-- omitted on CRDB: supabase_realtime

exception
  when duplicate_object then null;
  when undefined_object then null;
end $$;

-- authenticated: read own consent history and priority decision logs only
grant select on table
  public.model_training_consent_events,
  public.model_priority_runtime_snapshots
to authenticated;

-- service_role: full CRUD on all new control-plane tables (edge workers, cron)
grant all privileges on table
  public.model_training_consent_events,
  public.model_usage_realtime_windows,
  public.model_priority_runtime_snapshots,
  public.provider_capacity_windows
to service_role;

-- Optional Supabase Studio / read-replica roles when present in the project
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'dashboard_user') then
    execute 'grant all privileges on table public.model_training_consent_events to dashboard_user';
    execute 'grant all privileges on table public.model_usage_realtime_windows to dashboard_user';
    execute 'grant all privileges on table public.model_priority_runtime_snapshots to dashboard_user';
    execute 'grant all privileges on table public.provider_capacity_windows to dashboard_user';
  end if;

  if exists (select 1 from pg_roles where rolname = 'supabase_read_only_user') then
    execute 'grant select on table public.model_training_consent_events to supabase_read_only_user';
    execute 'grant select on table public.model_usage_realtime_windows to supabase_read_only_user';
    execute 'grant select on table public.model_priority_runtime_snapshots to supabase_read_only_user';
    execute 'grant select on table public.provider_capacity_windows to supabase_read_only_user';
  end if;
end $$;

